-- composition of rule kernels build_side_probe_side x duplicate_groups (duckdb), template graft_scalar
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['x'::text, NULL::text] AS c0, 10.0::float8 AS c1, (SELECT MIN ('-1 month'::interval) FROM t0 AS a3) AS c2 FROM (SELECT * FROM t3 WHERE (SELECT count(*) FROM (SELECT 10::bigint AS c0 EXCEPT SELECT 10::bigint AS c0 FROM t4 AS a1 GROUP BY a1.c1, a1.c0, a1.c3) AS kb) >= 0) AS a1 WHERE (SELECT BOOL_AND (TRUE) FROM t4 AS a2) UNION ALL SELECT ARRAY['1'::text] AS c0, 0.0::float8 AS c1, '00:00:00.000001'::interval AS c2;
